import { formatReportRange } from "./report-periods.js";
const e=value=>String(value??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const number=value=>Number.isFinite(Number(value))?Number(value):null;
const metric=(label,value)=>value==null?"":`<article class="card report-metric"><span>${e(label)}</span><strong>${e(value)}</strong></article>`;
const list=(rows,empty)=>rows?.length?`<ul class="clean-list">${rows.map(row=>`<li>${e(row.label)}${number(row.percent)!=null?` · %${number(row.percent)}`:""}</li>`).join("")}</ul>`:`<p class="meta">${e(empty)}</p>`;

export function learningReportView({children,selectedChildId,periodType,period,payload,history=[],loading=false,error=""}) {
  const summary=payload?.summary||{},vocab=payload?.vocabulary||{},hasData=Boolean(payload?.has_data),child=children.find(row=>String(row.id)===String(selectedChildId));
  return `<section class="learning-report-center" data-learning-report-center><div class="page-head"><div><p class="eyebrow">VELİ PANELİ</p><h1>Gelişim Raporları</h1><p class="lead">Kaydedilmiş öğrenme verilerinden haftalık ve aylık, güvenli gelişim özeti.</p></div><div class="button-row"><button class="button secondary" data-action="print-learning-report">Raporu Yazdır</button><button class="button secondary" data-route="parent">Veli paneline dön</button></div></div><section class="card report-controls"><label>Çocuk<select data-report-child>${children.map(row=>`<option value="${e(row.id)}" ${String(row.id)===String(selectedChildId)?"selected":""}>${e(row.name)}</option>`).join("")}</select></label><div class="report-tabs" role="tablist" aria-label="Rapor dönemi"><button class="button ${periodType==="weekly"?"primary":"secondary"}" data-report-period="weekly" role="tab" aria-selected="${periodType==="weekly"}">Haftalık</button><button class="button ${periodType==="monthly"?"primary":"secondary"}" data-report-period="monthly" role="tab" aria-selected="${periodType==="monthly"}">Aylık</button></div></section>${loading?`<article class="card" role="status">Rapor yükleniyor…</article>`:error?`<article class="card feedback incorrect" role="alert">${e(error)}</article>`:`<article class="report-print-area"><header class="card report-title"><p class="eyebrow">${periodType==="weekly"?"HAFTALIK":"AYLIK"} ÖN İZLEME</p><h2>${e(child?.name||"Öğrenci")}</h2><p>${e(formatReportRange(period))}</p></header>${hasData?`<div class="report-metrics">${metric("Tamamlanan ders",number(summary.completed_lessons))}${metric("Başlanan ders",number(summary.started_lessons))}${metric("Toplam cevap",number(summary.total_answers))}${metric("Başarı",number(summary.accuracy_percent)==null?null:`%${number(summary.accuracy_percent)}`)}</div>`:`<article class="card report-empty"><h2>Henüz yeterli veri yok</h2><p>${e(payload?.parent_comment||"Bu dönemde rapor oluşturacak yeterli çalışma kaydı bulunmuyor.")}</p></article>`}<div class="report-sections"><article class="card"><h2>Güçlü alanlar</h2>${list(payload?.topics?.strong,"Bu dönem için güvenilir konu verisi yok.")}</article><article class="card"><h2>Tekrar edilmesi gereken alanlar</h2>${list(payload?.topics?.review,"Bu dönem için güvenilir tekrar alanı yok.")}</article><article class="card"><h2>Kelime gelişimi</h2><p>Görülen: ${number(vocab.seen)??"—"} · Mastered: ${number(vocab.mastered)??"—"} · Tekrar zamanı: ${number(vocab.due)??"—"} · Zorlanılan: ${number(vocab.difficult)??"—"}</p></article><article class="card"><h2>Oyunlar ve hikâyeler</h2><p class="meta">Henüz sunucuya senkronlanan dönemsel oyun ve hikâye verisi yok.</p></article><article class="card report-parent-comment"><h2>Veliye kısa çalışma planı</h2><p>${e(payload?.parent_comment||"Henüz yeterli veri yok.")}</p></article></div></article>`}<section class="report-history"><div class="section-title-row"><div><h2>Önceki raporlar</h2><p class="meta">Tamamlanan dönemler değişmez snapshot olarak saklanır.</p></div><button class="button secondary" data-action="generate-previous-report">Önceki dönemi kaydet</button></div>${history.length?history.map(row=>`<button class="card report-history-row" data-report-id="${e(row.id)}"><strong>${row.period_type==="weekly"?"Haftalık":"Aylık"} rapor</strong><span>${e(formatReportRange({start:row.period_start,end:row.period_end}))}</span><small>Oluşturuldu: ${e(new Intl.DateTimeFormat("tr-TR",{dateStyle:"long",timeZone:"Europe/Istanbul"}).format(new Date(row.generated_at)))}</small></button>`).join(""):`<article class="card"><p>Henüz kaydedilmiş önceki rapor yok.</p></article>`}</section></section>`;
}
